update public.question_solution_steps set title='Aplique o critério', content_markdown='Aplique a negação a toda a conjunção. No enunciado, Qual expressão equivale a $overline{Acdot B}$? A tabela-verdade confirma igualdade em todos os casos.', sort_order=3 where id='70000000-0000-4000-8000-000009300513';
update public.question_solution_steps set title='Analise os distratores', content_markdown='“$overline Acdotoverline B$” não cumpre o critério técnico do caso: A tabela-verdade confirma igualdade em todos os casos. “$A+B$” não decorre do princípio aplicável: A lei de De Morgan troca AND por OR ao negar cada operando. “$Acdot B$” deixa de executar a análise necessária: Aplique a negação a toda a conjunção.', sort_order=4 where id='70000000-0000-4000-8000-000009300514';
update public.question_solution_steps set title='Verifique a conclusão', content_markdown='A alternativa correta é “$overline A+overline B$”, pois é a única que respeita o princípio e o cenário apresentados.', sort_order=5 where id='70000000-0000-4000-8000-000009300515';

update public.question_solutions set final_answer_markdown='$A$', explanation_markdown='Fatoração produz $A(B+overline B)$. No caso apresentado, Use complementaridade dentro dos parênteses. $B+overline B=1$, restando $A$. Logo, “$A$” é a conclusão correta. “$B$” não cumpre o critério técnico do caso: $B+overline B=1$, restando $A$. “$Acdot B$” não decorre do princípio aplicável: Fatoração produz $A(B+overline B)$. “$1$” deixa de executar a análise necessária: Use complementaridade dentro dos parênteses.' where question_id='40000000-0000-4000-8000-000000930052';
