update public.question_solution_steps set title='Analise os distratores', content_markdown='“$B$” não cumpre o critério técnico do caso: $B+overline B=1$, restando $A$. “$Acdot B$” não decorre do princípio aplicável: Fatoração produz $A(B+overline B)$. “$1$” deixa de executar a análise necessária: Use complementaridade dentro dos parênteses.', sort_order=4 where id='70000000-0000-4000-8000-000009300524';
update public.question_solution_steps set title='Verifique a conclusão', content_markdown='A alternativa correta é “$A$”, pois é a única que respeita o princípio e o cenário apresentados.', sort_order=5 where id='70000000-0000-4000-8000-000009300525';

update public.question_solutions set final_answer_markdown='Quando as entradas são diferentes.', explanation_markdown='XOR representa desigualdade entre dois bits. No caso apresentado, Compare os quatro pares possíveis de entrada. Apenas $01$ e $10$ ativam a saída. Logo, “Quando as entradas são diferentes.” é a conclusão correta. “Quando ambas são $1$.” não cumpre o critério técnico do caso: Apenas $01$ e $10$ ativam a saída. “Quando ambas são $0$.” não decorre do princípio aplicável: XOR representa desigualdade entre dois bits. “Quando o clock sobe.” deixa de executar a análise necessária: Compare os quatro pares possíveis de entrada.' where question_id='40000000-0000-4000-8000-000000930053';
update public.question_solution_steps set title='Delimite o problema', content_markdown='O enunciado apresenta esta situação de portas lógicas: Quando uma porta XOR de duas entradas produz $1$?', sort_order=1 where id='70000000-0000-4000-8000-000009300531';
update public.question_solution_steps set title='Recupere o princípio', content_markdown='XOR representa desigualdade entre dois bits.', sort_order=2 where id='70000000-0000-4000-8000-000009300532';
