update public.question_solution_steps set title='Analise os distratores', content_markdown='“Quando ambas são $1$.” não cumpre o critério técnico do caso: Apenas $01$ e $10$ ativam a saída. “Quando ambas são $0$.” não decorre do princípio aplicável: XOR representa desigualdade entre dois bits. “Quando o clock sobe.” deixa de executar a análise necessária: Compare os quatro pares possíveis de entrada.', sort_order=4 where id='70000000-0000-4000-8000-000009300534';
update public.question_solution_steps set title='Verifique a conclusão', content_markdown='A alternativa correta é “Quando as entradas são diferentes.”, pois é a única que respeita o princípio e o cenário apresentados.', sort_order=5 where id='70000000-0000-4000-8000-000009300535';

update public.question_solutions set final_answer_markdown='Porque combinações de NAND implementam NOT, AND e OR.', explanation_markdown='Funcionalidade universal vem de poder construir um conjunto funcionalmente completo. No caso apresentado, Comece construindo NOT com entradas NAND unidas. Depois de NOT, De Morgan permite formar AND e OR. Logo, “Porque combinações de NAND implementam NOT, AND e OR.” é a conclusão correta. “Porque armazena um bit.” não cumpre o critério técnico do caso: Depois de NOT, De Morgan permite formar AND e OR. “Porque só aceita uma entrada.” não decorre do princípio aplicável: Funcionalidade universal vem de poder construir um conjunto funcionalmente completo. “Porque substitui o clock.” deixa de executar a análise necessária: Comece construindo NOT com entradas NAND unidas.' where question_id='40000000-0000-4000-8000-000000930054';
update public.question_solution_steps set title='Delimite o problema', content_markdown='O enunciado apresenta esta situação de portas universais: Por que NAND é considerada porta universal?', sort_order=1 where id='70000000-0000-4000-8000-000009300541';
