update public.question_solution_steps set title='Aplique o critério', content_markdown='Comece construindo NOT com entradas NAND unidas. No enunciado, Por que NAND é considerada porta universal? Depois de NOT, De Morgan permite formar AND e OR.', sort_order=3 where id='70000000-0000-4000-8000-000009300543';
update public.question_solution_steps set title='Analise os distratores', content_markdown='“Porque armazena um bit.” não cumpre o critério técnico do caso: Depois de NOT, De Morgan permite formar AND e OR. “Porque só aceita uma entrada.” não decorre do princípio aplicável: Funcionalidade universal vem de poder construir um conjunto funcionalmente completo. “Porque substitui o clock.” deixa de executar a análise necessária: Comece construindo NOT com entradas NAND unidas.', sort_order=4 where id='70000000-0000-4000-8000-000009300544';
update public.question_solution_steps set title='Verifique a conclusão', content_markdown='A alternativa correta é “Porque combinações de NAND implementam NOT, AND e OR.”, pois é a única que respeita o princípio e o cenário apresentados.', sort_order=5 where id='70000000-0000-4000-8000-000009300545';

update public.question_solutions set final_answer_markdown='São logicamente equivalentes.', explanation_markdown='Equivalência lógica depende da função, não da implementação física. No caso apresentado, Compare tabelas-verdade ou simplifique as expressões. Mesmo comportamento não garante custo ou atraso iguais. Logo, “São logicamente equivalentes.” é a conclusão correta. “Têm a mesma quantidade de portas.” não cumpre o critério técnico do caso: Mesmo comportamento não garante custo ou atraso iguais. “Possuem o mesmo atraso.” não decorre do princípio aplicável: Equivalência lógica depende da função, não da implementação física. “Usam a mesma tecnologia física.” deixa de executar a análise necessária: Compare tabelas-verdade ou simplifique as expressões.' where question_id='40000000-0000-4000-8000-000000930055';
