update public.question_solution_steps set title='Recupere o princípio', content_markdown='Equivalência lógica depende da função, não da implementação física.', sort_order=2 where id='70000000-0000-4000-8000-000009300552';
update public.question_solution_steps set title='Aplique o critério', content_markdown='Compare tabelas-verdade ou simplifique as expressões. No enunciado, Dois circuitos têm expressões diferentes, mas mesma saída para todas as entradas. Qual conclusão é válida? Mesmo comportamento não garante custo ou atraso iguais.', sort_order=3 where id='70000000-0000-4000-8000-000009300553';
