update public.question_solutions set final_answer_markdown='Encaminhar uma entre oito entradas para uma saída.', explanation_markdown='Linhas de seleção escolhem qual entrada aparece na saída. No caso apresentado, Observe se o bloco escolhe, expande ou armazena informação. Um MUX concentra várias fontes em um destino. Logo, “Encaminhar uma entre oito entradas para uma saída.” é a conclusão correta. “Decodificar uma entrada em oito saídas.” não cumpre o critério técnico do caso: Um MUX concentra várias fontes em um destino. “Somar oito operandos.” não decorre do princípio aplicável: Linhas de seleção escolhem qual entrada aparece na saída. “Guardar oito bits.” deixa de executar a análise necessária: Observe se o bloco escolhe, expande ou armazena informação.' where question_id='40000000-0000-4000-8000-000000930056';
