update public.question_solutions set final_answer_markdown='$4$', explanation_markdown='$n$ seletores distinguem $2^n$ entradas. No caso apresentado, Resolva $2^n=16$. Quatro bits codificam dezesseis escolhas. Logo, “$4$” é a conclusão correta. “$2$” não cumpre o critério técnico do caso: Quatro bits codificam dezesseis escolhas. “$8$” não decorre do princípio aplicável: $n$ seletores distinguem $2^n$ entradas. “$16$” deixa de executar a análise necessária: Resolva $2^n=16$.' where question_id='40000000-0000-4000-8000-000000930057';
