update public.question_solutions set final_answer_markdown='Soma $0$ e carry $1$.', explanation_markdown='Soma é XOR; carry é AND. No caso apresentado, Avalie as duas portas para o par $11$. $1oplus1=0$ e $1cdot1=1$. Logo, “Soma $0$ e carry $1$.” é a conclusão correta. “Soma $1$ e carry $0$.” não cumpre o critério técnico do caso: $1oplus1=0$ e $1cdot1=1$. “Soma $1$ e carry $1$.” não decorre do princípio aplicável: Soma é XOR; carry é AND. “Soma $0$ e carry $0$.” deixa de executar a análise necessária: Avalie as duas portas para o par $11$.' where question_id='40000000-0000-4000-8000-000000930058';
