update public.question_solution_steps set title='Recupere o princípio', content_markdown='Soma é XOR; carry é AND.', sort_order=2 where id='70000000-0000-4000-8000-000009300582';
update public.question_solution_steps set title='Aplique o critério', content_markdown='Avalie as duas portas para o par $11$. No enunciado, Para entradas $A=1$ e $B=1$, quais são soma e carry de um meio somador? $1oplus1=0$ e $1cdot1=1$.', sort_order=3 where id='70000000-0000-4000-8000-000009300583';
update public.question_solution_steps set title='Analise os distratores', content_markdown='“Soma $1$ e carry $0$.” não cumpre o critério técnico do caso: $1oplus1=0$ e $1cdot1=1$. “Soma $1$ e carry $1$.” não decorre do princípio aplicável: Soma é XOR; carry é AND. “Soma $0$ e carry $0$.” deixa de executar a análise necessária: Avalie as duas portas para o par $11$.', sort_order=4 where id='70000000-0000-4000-8000-000009300584';
update public.question_solution_steps set title='Verifique a conclusão', content_markdown='A alternativa correta é “Soma $0$ e carry $1$.”, pois é a única que respeita o princípio e o cenário apresentados.', sort_order=5 where id='70000000-0000-4000-8000-000009300585';

update public.question_solutions set final_answer_markdown='Para somar também o transporte vindo da posição menos significativa.', explanation_markdown='Em palavras multibit, cada coluna pode receber transporte da anterior. No caso apresentado, Considere a soma de três bits: dois operandos e carry-in. Sem carry-in, o circuito falha em cadeias de soma. Logo, “Para somar também o transporte vindo da posição menos significativa.” é a conclusão correta. “Para guardar resultados antigos.” não cumpre o critério técnico do caso: Sem carry-in, o circuito falha em cadeias de soma. “Para inverter o operando.” não decorre do princípio aplicável: Em palavras multibit, cada coluna pode receber transporte da anterior. “Para escolher o clock.” deixa de executar a análise necessária: Considere a soma de três bits: dois operandos e carry-in.' where question_id='40000000-0000-4000-8000-000000930059';
