update public.question_solution_steps set title='Aplique o critério', content_markdown='Considere a soma de três bits: dois operandos e carry-in. No enunciado, Por que um somador completo precisa de entrada de carry? Sem carry-in, o circuito falha em cadeias de soma.', sort_order=3 where id='70000000-0000-4000-8000-000009300593';
