update public.question_solutions set final_answer_markdown='Copia D para Q.', explanation_markdown='Flip-flop D amostra seu dado na borda e o mantém até nova borda. No caso apresentado, Observe D imediatamente no evento ativo. Q passa a refletir a amostra de D. Logo, “Copia D para Q.” é a conclusão correta. “Inverte Q sempre.” não cumpre o critério técnico do caso: Q passa a refletir a amostra de D. “Soma D a Q.” não decorre do princípio aplicável: Flip-flop D amostra seu dado na borda e o mantém até nova borda. “Zera todas as saídas.” deixa de executar a análise necessária: Observe D imediatamente no evento ativo.' where question_id='40000000-0000-4000-8000-000000930064';
