update public.question_solutions set final_answer_markdown='O latch pode acompanhar a entrada durante um nível ativo.', explanation_markdown='Latch é sensível a nível; flip-flop, tipicamente, a transição de borda. No caso apresentado, Compare uma janela de transparência com um instante de amostragem. A janela do latch pode permitir alterações enquanto está habilitado. Logo, “O latch pode acompanhar a entrada durante um nível ativo.” é a conclusão correta. “O flip-flop não armazena bits.” não cumpre o critério técnico do caso: A janela do latch pode permitir alterações enquanto está habilitado. “O latch não usa controle.” não decorre do princípio aplicável: Latch é sensível a nível; flip-flop, tipicamente, a transição de borda. “Ambos só funcionam sem clock.” deixa de executar a análise necessária: Compare uma janela de transparência com um instante de amostragem.' where question_id='40000000-0000-4000-8000-000000930065';
