update public.question_solutions set final_answer_markdown='$8$', explanation_markdown='São necessários quatro bancos de endereços e dois chips em paralelo por palavra. No caso apresentado, Separe expansão de profundidade ($4K/1K$) e largura ($16/8$). $4	imes2=8$ chips atendem ambos os requisitos. Logo, “$8$” é a conclusão correta. “$2$” não cumpre o critério técnico do caso: $4	imes2=8$ chips atendem ambos os requisitos. “$4$” não decorre do princípio aplicável: São necessários quatro bancos de endereços e dois chips em paralelo por palavra. “$16$” deixa de executar a análise necessária: Separe expansão de profundidade ($4K/1K$) e largura ($16/8$).' where question_id='40000000-0000-4000-8000-000000930072';
update public.question_solution_steps set title='Delimite o problema', content_markdown='O enunciado apresenta esta situação de composição de memória: Para construir memória $4K	imes16$ usando chips $1K	imes8$, quantos chips são necessários?', sort_order=1 where id='70000000-0000-4000-8000-000009300721';
update public.question_solution_steps set title='Recupere o princípio', content_markdown='São necessários quatro bancos de endereços e dois chips em paralelo por palavra.', sort_order=2 where id='70000000-0000-4000-8000-000009300722';
update public.question_solution_steps set title='Aplique o critério', content_markdown='Separe expansão de profundidade ($4K/1K$) e largura ($16/8$). No enunciado, Para construir memória $4K	imes16$ usando chips $1K	imes8$, quantos chips são necessários? $4	imes2=8$ chips atendem ambos os requisitos.', sort_order=3 where id='70000000-0000-4000-8000-000009300723';
update public.question_solution_steps set title='Analise os distratores', content_markdown='“$2$” não cumpre o critério técnico do caso: $4	imes2=8$ chips atendem ambos os requisitos. “$4$” não decorre do princípio aplicável: São necessários quatro bancos de endereços e dois chips em paralelo por palavra. “$16$” deixa de executar a análise necessária: Separe expansão de profundidade ($4K/1K$) e largura ($16/8$).', sort_order=4 where id='70000000-0000-4000-8000-000009300724';
update public.question_solution_steps set title='Verifique a conclusão', content_markdown='A alternativa correta é “$8$”, pois é a única que respeita o princípio e o cenário apresentados.', sort_order=5 where id='70000000-0000-4000-8000-000009300725';

update public.question_solutions set final_answer_markdown='Ativar o dispositivo cujo intervalo de endereços foi selecionado.', explanation_markdown='O endereço identifica o destino; o decodificador gera o sinal de seleção. No caso apresentado, Siga o endereço desde o barramento até o chip selecionado. Só o dispositivo correspondente deve responder à transação. Logo, “Ativar o dispositivo cujo intervalo de endereços foi selecionado.” é a conclusão correta. “Converter dados em instruções.” não cumpre o critério técnico do caso: Só o dispositivo correspondente deve responder à transação. “Aumentar a largura do barramento.” não decorre do princípio aplicável: O endereço identifica o destino; o decodificador gera o sinal de seleção. “Sincronizar flip-flops.” deixa de executar a análise necessária: Siga o endereço desde o barramento até o chip selecionado.' where question_id='40000000-0000-4000-8000-000000930073';
