update public.question_solutions set final_answer_markdown='Para reduzir risco de metastabilidade e eventos mal amostrados.', explanation_markdown='Domínios temporais diferentes não garantem setup/hold entre si. No caso apresentado, Relacione a chegada imprevisível do sinal à borda do clock local. Sincronizadores dão tempo para resolver estados instáveis. Logo, “Para reduzir risco de metastabilidade e eventos mal amostrados.” é a conclusão correta. “Para aumentar o tamanho da ROM.” não cumpre o critério técnico do caso: Sincronizadores dão tempo para resolver estados instáveis. “Para evitar complemento de dois.” não decorre do princípio aplicável: Domínios temporais diferentes não garantem setup/hold entre si. “Para eliminar o barramento.” deixa de executar a análise necessária: Relacione a chegada imprevisível do sinal à borda do clock local.' where question_id='40000000-0000-4000-8000-000000930075';
